/**
 * 内容指纹：抓"同一份字节被发给不同歌曲"的占位载荷。
 *
 * 现场成因（2026-11-12 生产实测）：某个聚合音源的上游掉线后，对**每一首**请求都返回
 * 同一条 TTS 语音 MP3（118,995 字节 / 19.75 秒 / 单声道 24kHz，ID3 里写着
 * `Audio generated by ttsmaker.cn`）。它 HTTP 200、容器合法、时长也过得了嗅探，
 * 于是取址层判"成功"，瀑布不再往下一个源走 —— 用户连听几首都是同一句语音。
 *
 * 判据为什么是"同一份内容 + 不同歌曲"：
 * - 真试听片段每首字节都不同，永远撞不上指纹 ⇒ 不误伤试听；
 * - 源不认音质档、对 `320k` 与 `flac` 返回同一个文件是**合法行为**，所以同一首歌的
 *   不同音质必须排除，只认 songmid 不同；
 * - 首次只登记不判定：要等第二首撞上同一指纹才定性。代价说清楚 —— 第一首照样被放行
 *   （没有历史就无从知道它是占位符），第二首在完成后定性并记坏，第三首起在首块阶段
 *   当场拒绝、无感换源；两次坏样本即触发账本冷却。
 *
 * 只取前 32KiB 而不是整文件：完成时从文件里精确读 32KiB；首块只有在**不短于** 32KiB
 * 时才可比 —— 短块哈希与文件头哈希结构上不可能相等，那种情况跳过而不是猜。
 */
import { createHash } from 'node:crypto'

/** 参与比对的头部长度 */
const HEAD_BYTES = 32_768
/** 最多记住多少个歌曲键，超出按插入序淘汰 */
const MAX_KEYS = 8_192

/** 歌曲身份：cacheKey 是 `${source}:${songmid}:${quality}`，音质档不算另一首歌 */
function songIdentity(cacheKey: string): string {
  const parts = cacheKey.split(':')
  if (parts.length < 3) return cacheKey
  return `${parts[0]}:${parts.slice(1, parts.length - 1).join(':')}`
}

/** 只有拿满 32KiB 才给出可比指纹 */
export function headFingerprint(bytes: Uint8Array | null | undefined): string | null {
  if (!bytes || bytes.length < HEAD_BYTES) return null
  return createHash('sha256').update(bytes.subarray(0, HEAD_BYTES)).digest('hex')
}

/**
 * 边收边攒头部（32KiB）的累加器。
 *
 * 为什么不用"完成后再开文件读头部"：那会在 `checkTrialAudio` 与写库之间多插一个
 * await，把 `entry.done` 往后推 —— 既有测试是"响应体一结束就断言落库"，多一个
 * 异步跳就会变成竞态；生产上也让缓存行写得比实际更晚。攒够 32KiB 后停止拷贝。
 */
export function createHeadAccumulator(): {
  note: (chunk: Uint8Array) => void
  hash: () => string | null
} {
  const head = new Uint8Array(HEAD_BYTES)
  let filled = 0
  let digest: string | null = null
  return {
    note(chunk: Uint8Array): void {
      if (digest !== null) return
      const take = Math.min(chunk.length, HEAD_BYTES - filled)
      head.set(chunk.subarray(0, take), filled)
      filled += take
      if (filled >= HEAD_BYTES) digest = createHash('sha256').update(head).digest('hex')
    },
    hash(): string | null {
      return digest
    },
  }
}

interface Sight {
  /** 同一份头部字节 + 同一声明大小下，第一个看到它的歌曲身份 */
  song: string
  /** 已定性为占位载荷：只有它会让后续请求在首块阶段就被拒 */
  placeholder: boolean
}

/** key = `${headHash}:${size}` */
const sights = new Map<string, Sight>()

function sightKey(headHash: string, size: number): string {
  return `${headHash}:${size}`
}

/**
 * 首块阶段（交付尚未开始）：命中已定性的占位指纹就拒绝这次载荷。
 * 返回那条指纹最早出现时的歌曲身份，供日志说明"和哪首撞了"。
 */
export function matchKnownPlaceholder(args: {
  cacheKey: string
  size: number
  headHash: string | null
}): { otherSong: string } | null {
  if (!args.headHash) return null
  const sight = sights.get(sightKey(args.headHash, args.size))
  if (!sight || !sight.placeholder) return null
  const song = songIdentity(args.cacheKey)
  if (sight.song === song) return null
  return { otherSong: sight.song }
}

/**
 * 完成阶段（字节已落盘）：登记或定性。需要**两个独立信号同时成立**才定性为占位：
 * ① 同一份内容已经发给过别的歌；② 这一份的时长与期望差得太远（`trial`）。
 *
 * 为什么必须叠第二个信号：曲库里两首不同 songmid 拿到**同一份完整录音**是合法情形
 * （重复上架、翻唱登记成正版那类），只按"内容相同"判会把它们当占位符拒掉，
 * 用户从"能听"退化成"报错"。而占位语音的特征恰恰是内容相同**且**短得对不上整曲。
 * 只撞内容、时长没撞的记成 `duplicate-ordinary`：留痕、不改变交付行为。
 */
export function observeCompleted(args: {
  cacheKey: string
  size: number
  headHash: string | null
  trial: boolean
}): {
  verdict: 'first' | 'same-song' | 'duplicate-ordinary' | 'placeholder'
  otherSong?: string
  reason?: string
} {
  if (!args.headHash) return { verdict: 'first', reason: '头部不足 32KiB，未参与指纹' }

  const key = sightKey(args.headHash, args.size)
  const song = songIdentity(args.cacheKey)
  const sight = sights.get(key)

  if (!sight) {
    if (sights.size >= MAX_KEYS) {
      const oldest = sights.keys().next()
      if (!oldest.done) sights.delete(oldest.value)
    }
    sights.set(key, { song, placeholder: false })
    return { verdict: 'first' }
  }

  // 命中同一首歌：源不认音质档也走这里，属合法行为
  if (sight.song === song) return { verdict: 'same-song' }

  if (!args.trial) return { verdict: 'duplicate-ordinary', otherSong: sight.song }

  if (!sight.placeholder) {
    sights.set(key, { ...sight, placeholder: true })
  }
  return { verdict: 'placeholder', otherSong: sight.song }
}

/** 只给单测与面板诊断用 */
export function fingerprintStats(): { entries: number; placeholders: number } {
  let placeholders = 0
  for (const sight of sights.values()) if (sight.placeholder) placeholders++
  return { entries: sights.size, placeholders }
}

export function resetFingerprintsForTest(): void {
  sights.clear()
}
